import itertools
import json

def solve_puzzle():
    # Define categories and values
    houses = [1, 2, 3]
    Names = ['Eric', 'Peter', 'Arnold']
    Smoothies = ['cherry', 'watermelon', 'desert']
    Flowers = ['carnations', 'lilies', 'daffodils']
    Animals = ['cat', 'horse', 'bird']
    Hobbies = ['photography', 'cooking', 'gardening']

    solutions = []

    # Iterate over all permutations for each category
    for name_perm in itertools.permutations(Names):
        # Quick pruning: "The photography enthusiast is Eric."
        # If this can't be satisfied at all, skip early.
        # We can't check yet because we don't have hobby_perm, but we can ensure
        # that Eric and Peter are distinct, which is always true by permutation.
        for smoothie_perm in itertools.permutations(Smoothies):
            for flower_perm in itertools.permutations(Flowers):
                # Equality constraints prune early
                # 2. bird = cherry -> cannot check yet without animals, skip
                # 3. cooking = desert -> cannot check yet without hobbies, skip
                # 4. gardening = carnations -> cannot check yet without hobbies, skip
                # 6. daffodils = desert
                if flower_perm.index('daffodils') != smoothie_perm.index('desert'):
                    continue
                for animal_perm in itertools.permutations(Animals):
                    # 2. bird = cherry
                    if animal_perm.index('bird') != smoothie_perm.index('cherry'):
                        continue
                    # 7. watermelon = horse
                    if smoothie_perm.index('watermelon') != animal_perm.index('horse'):
                        continue
                    for hobby_perm in itertools.permutations(Hobbies):
                        # 3. cooking = desert
                        if hobby_perm.index('cooking') != smoothie_perm.index('desert'):
                            continue
                        # 4. gardening = carnations
                        if hobby_perm.index('gardening') != flower_perm.index('carnations'):
                            continue
                        # 8. photography = Eric
                        if hobby_perm.index('photography') != name_perm.index('Eric'):
                            continue
                        # 1. horse next to photography
                        if abs(animal_perm.index('horse') - hobby_perm.index('photography')) != 1:
                            continue
                        # 5. cooking directly left of Peter
                        if name_perm.index('Peter') != hobby_perm.index('cooking') + 1:
                            continue

                        # If all constraints satisfied, record solution
                        solution_rows = []
                        for i in range(3):
                            solution_rows.append([
                                str(houses[i]),
                                name_perm[i],
                                smoothie_perm[i],
                                flower_perm[i],
                                animal_perm[i],
                                hobby_perm[i]
                            ])
                        solutions.append(solution_rows)

    # Choose the first solution (should be unique for a well-posed puzzle)
    if not solutions:
        raise ValueError("No solution found.")
    result = {
        "solution": {
            "header": ["House", "Name", "Smoothie", "Flower", "Animal", "Hobby"],
            "rows": solutions[0]
        }
    }
    return result

if __name__ == "__main__":
    print(json.dumps(solve_puzzle(), ensure_ascii=False))
